from taf.gnb.oam.coam.cu.utilities.http_client import HttpClient


class AGENTv1HttpClient(HttpClient):
    """ This class provides a client for the AGENT v1 API. """
    def __init__(self, base_url, connection_alias):
        super(AGENTv1HttpClient, self).__init__(connection_alias)
        self.base_url = base_url + "/api/agent/v1"

    def activate_cu_vnf(self, timeout):
        endpoint = "/georedundancy/cu-vnf/operations/activations"
        headers = {
            "accept": "application/json"
        }
        return self._send_post_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def get_activate_cu_vnf_status(self, operation_id, timeout):
        endpoint = f"/georedundancy/cu-vnf/operations/activations/{operation_id}"
        headers = {
            "accept": "application/json"
        }

        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def forcefully_activate_cu_vnf(self, timeout):
        endpoint = "/georedundancy/cu-vnf/operations/forced-activations"
        headers = {
            "accept": "application/json"
        }
        return self._send_post_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def get_forcefully_activate_cu_vnf_status(self, operation_id, timeout):
        endpoint = f"/georedundancy/cu-vnf/operations/forced-activations/{operation_id}"
        headers = {
            "accept": "application/json"
        }

        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def deactivate_cu_vnf(self, timeout):
        endpoint = "/georedundancy/cu-vnf/operations/deactivations"
        headers = {
            "accept": "application/json"
        }

        return self._send_post_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def get_deactivate_cu_vnf_status(self, operation_id, timeout):
        endpoint = f"/georedundancy/cu-vnf/operations/deactivations/{operation_id}"
        headers = {
            "accept": "application/json"
        }

        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def get_cu_vnf(self, timeout):
        endpoint = "/georedundancy/cu-vnf"
        headers = {
            "accept": "application/json"
        }

        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def reset_cu(self, timeout):
        endpoint = "/cu/operations/resets"
        headers = {
            "accept": "application/json"
        }

        return self._send_post_request(endpoint=endpoint, headers=headers, timeout=timeout)
